//! Hashers used by the [`HopscotchMap`](super::HopscotchMap) port.
//!
//! The C++ original instantiates `tsl::hopscotch_map<int, int>`, which defaults
//! to `std::hash<int>`.  In libstdc++ that specialisation is the *identity*
//! function: the integer is reinterpreted as a `size_t` and returned unchanged.
//! Combined with the power-of-two growth policy of the table this makes the
//! insertion of the keys `0, 1, 2, ...` collision-free, which is exactly the
//! behaviour the C++ program relies on for its speed.
//!
//! [`IdentityHasher`] reproduces that, and falls back to FNV-1a for
//! byte-oriented keys (`str`, `String`, `[u8]`, ...) which have no meaningful
//! identity representation.  [`MixingHasher`] is offered for key distributions
//! where identity hashing clusters badly (for example keys that only differ in
//! their high bits); the table is generic over
//! [`BuildHasher`](std::hash::BuildHasher), so either can be plugged in.

#![allow(dead_code)]

use std::hash::{BuildHasher, Hasher};

const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

/// Multiplicative constant for Fibonacci hashing: 2^64 / phi, rounded to odd.
const FIBONACCI: u64 = 0x9e37_79b9_7f4a_7c15;

/// A `Hasher` that mirrors libstdc++'s `std::hash` for primitive integers.
///
/// Integer writes replace the state with the value itself; byte writes run
/// FNV-1a so that string keys still spread reasonably.
#[derive(Clone, Copy, Debug, Default)]
pub struct IdentityHasher {
    state: u64,
}

impl IdentityHasher {
    pub fn new() -> IdentityHasher {
        IdentityHasher { state: 0 }
    }
}

impl Hasher for IdentityHasher {
    fn finish(&self) -> u64 {
        self.state
    }

    fn write(&mut self, bytes: &[u8]) {
        let mut hash = if self.state == 0 {
            FNV_OFFSET_BASIS
        } else {
            self.state
        };
        for &byte in bytes {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(FNV_PRIME);
        }
        self.state = hash;
    }

    fn write_u8(&mut self, value: u8) {
        self.state = value as u64;
    }

    fn write_u16(&mut self, value: u16) {
        self.state = value as u64;
    }

    fn write_u32(&mut self, value: u32) {
        self.state = value as u64;
    }

    fn write_u64(&mut self, value: u64) {
        self.state = value;
    }

    fn write_usize(&mut self, value: usize) {
        self.state = value as u64;
    }

    fn write_i8(&mut self, value: i8) {
        self.state = value as i64 as u64;
    }

    fn write_i16(&mut self, value: i16) {
        self.state = value as i64 as u64;
    }

    fn write_i32(&mut self, value: i32) {
        self.state = value as i64 as u64;
    }

    fn write_i64(&mut self, value: i64) {
        self.state = value as u64;
    }

    fn write_isize(&mut self, value: isize) {
        self.state = value as i64 as u64;
    }

    fn write_u128(&mut self, value: u128) {
        self.state = (value as u64) ^ ((value >> 64) as u64);
    }

    fn write_i128(&mut self, value: i128) {
        self.write_u128(value as u128);
    }
}

