#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::Hash;

    fn hash_of<T: Hash, B: BuildHasher>(builder: &B, value: &T) -> u64 {
        let mut hasher = builder.build_hasher();
        value.hash(&mut hasher);
        hasher.finish()
    }

    #[test]
    fn integers_hash_to_themselves() {
        let builder = BuildIdentityHasher::new();
        for value in [0i32, 1, 2, 7, 12345, i32::MAX] {
            assert_eq!(hash_of(&builder, &value), value as u64);
        }
        // Negative values keep the two's-complement bit pattern, exactly like
        // `static_cast<std::size_t>(x)` in libstdc++.
        assert_eq!(hash_of(&builder, &-1i32), u64::MAX);
    }

    #[test]
    fn strings_are_spread_by_fnv1a() {
        let builder = BuildIdentityHasher::new();
        assert_ne!(hash_of(&builder, &"alpha"), hash_of(&builder, &"beta"));
        assert_eq!(hash_of(&builder, &"alpha"), hash_of(&builder, &"alpha"));
    }

    #[test]
    fn mixing_hasher_spreads_low_bits() {
        let builder = BuildMixingHasher::new();
        // Keys that all share the low 12 bits must not share them after mixing.
        let masked: Vec<u64> = (0..8u64)
            .map(|i| hash_of(&builder, &(i << 12)) & 0xfff)
            .collect();
        let distinct: std::collections::BTreeSet<u64> = masked.iter().copied().collect();
        assert!(distinct.len() > 1, "mixing hasher failed to spread: {masked:?}");
    }
}

1	//! The hopscotch-hashing table that backs [`HopscotchMap`](super::HopscotchMap).
2	//!
3	//! # Algorithm
4	//!
5	//! Hopscotch hashing is open addressing with a bounded lookup cost.  Every key
6	//! has a *home bucket* `h = hash(key) & (bucket_count - 1)`.  The entry itself
7	//! may live in any of the [`NEIGHBOURHOOD_SIZE`] slots starting at `h`, and the
8	//! home bucket keeps a bitmap (`neighbourhood`) whose bit `d` is set when the
9	//! slot `h + d` stores an entry belonging to `h`.
10	//!
11	//! * A lookup only ever inspects the bits set in the home bucket's bitmap, so
12	//!   it touches at most [`NEIGHBOURHOOD_SIZE`] slots — all inside one or two
13	//!   cache lines.
14	//! * An insertion linearly probes for a free slot.  If that slot is farther
15	//!   than the neighbourhood allows, the free slot is *hopped* backwards: an
16	//!   entry that sits between the free slot and its own home is relocated into
17	//!   the free slot, which frees its previous slot closer to `h`.  This repeats
18	//!   until the free slot is inside `h`'s neighbourhood.
19	//! * If no hop sequence succeeds the table grows (rehash into twice as many
20	//!   buckets), which spreads the offending cluster.  As a final fallback the
21	//!   entry goes into an unbounded overflow list, mirroring the overflow
22	//!   container of `tsl::hopscotch_hash`.  This guarantees that insertion always
23	//!   terminates, even for a pathological hasher that maps every key to the same
24	//!   bucket.
25	//!
26	//! The bucket array is allocated with `NEIGHBOURHOOD_SIZE - 1` extra slots past
27	//! `bucket_count` so neighbourhoods never wrap around the end of the array;
28	//! those trailing slots are valid storage but are never home buckets.
29	//!
30	//! # Positions
31	//!
32	//! Iteration and lookup results are expressed as a flat [`Pos`]: values below
33	//! `slots()` index the bucket array, values from `slots()` upwards index the
34	//! overflow list, and [`HopscotchHash::end_pos`] is one past the last of them.
35	//! A `Pos` plays the role of a C++ iterator; like a C++ iterator it is
36	//! invalidated by any operation that rehashes the table.
37	
38	#![allow(dead_code)]
39	
40	use std::hash::{BuildHasher, Hash, Hasher};
41	
42	use super::hash::BuildIdentityHasher;
43	
44	/// Number of slots (including the home bucket itself) an entry may occupy,
45	/// which is also the width of the neighbourhood bitmap.
46	pub const NEIGHBOURHOOD_SIZE: usize = 32;
47	
48	/// Bucket count used for the first allocation; always a power of two.
49	pub const INITIAL_BUCKET_COUNT: usize = 16;
50	
51	/// Default load factor at which the table doubles.
52	pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.9;
53	
54	/// Upper bound on the linear probe for a free slot.  Keeps a single insertion
55	/// bounded even in a nearly full table; failing the probe just grows the table.
56	const MAX_PROBE_LENGTH: usize = 8 * NEIGHBOURHOOD_SIZE;
57	
58	/// How often a single insertion may grow the table while trying to find a slot
59	/// inside the key's neighbourhood before giving up and using the overflow list.
60	const MAX_GROW_ATTEMPTS: usize = 2;
61	
62	/// A flat position inside the table; see the [module docs](self#positions).
63	pub type Pos = usize;
64	
65	/// One slot of the bucket array.
66	pub struct Bucket<K, V> {
67	    /// Bit `d` is set when slot `self + d` holds an entry homed at `self`.
68	    neighbourhood: u32,
69	    entry: Option<(K, V)>,
70	}
71	
72	impl<K, V> Bucket<K, V> {
73	    const fn vacant() -> Bucket<K, V> {
74	        Bucket {
75	            neighbourhood: 0,
76	            entry: None,
77	        }
78	    }
79	
80	    /// True when this slot stores no entry.
81	    pub fn is_vacant(&self) -> bool {
82	        self.entry.is_none()
83	    }
84	
85	    /// The stored key/value pair, if any.
86	    pub fn entry(&self) -> Option<&(K, V)> {
87	        self.entry.as_ref()
88	    }
89	
90	    /// The raw neighbourhood bitmap of this bucket.
91	    pub fn neighbourhood(&self) -> u32 {
92	        self.neighbourhood
93	    }
94	}
