96	/// An open-addressed hash table using hopscotch hashing.
97	pub struct HopscotchHash<K, V, S = BuildIdentityHasher> {
98	    /// `bucket_count + NEIGHBOURHOOD_SIZE - 1` slots, or empty when unallocated.
99	    buckets: Vec<Bucket<K, V>>,
100	    /// Entries that did not fit into any neighbourhood.
101	    overflow: Vec<(K, V)>,
102	    /// Number of home buckets; a power of two, or zero before first allocation.
103	    bucket_count: usize,
104	    len: usize,
105	    max_load_factor: f32,
106	    /// Cached `floor(bucket_count * max_load_factor)`.
107	    grow_at: usize,
108	    hash_builder: S,
109	}
110	
111	impl<K, V> HopscotchHash<K, V, BuildIdentityHasher>
112	where
113	    K: Hash + Eq,
114	{
115	    /// An empty table that allocates on first insertion.
116	    pub fn new() -> HopscotchHash<K, V, BuildIdentityHasher> {
117	        HopscotchHash::with_hasher(BuildIdentityHasher::new())
118	    }
119	
120	    /// An empty table sized to hold `capacity` entries without rehashing.
121	    pub fn with_capacity(capacity: usize) -> HopscotchHash<K, V, BuildIdentityHasher> {
122	        HopscotchHash::with_capacity_and_hasher(capacity, BuildIdentityHasher::new())
123	    }
124	}
125	
126	impl<K, V> Default for HopscotchHash<K, V, BuildIdentityHasher>
127	where
128	    K: Hash + Eq,
129	{
130	    fn default() -> HopscotchHash<K, V, BuildIdentityHasher> {
131	        HopscotchHash::new()
132	    }
133	}
134	
135	impl<K, V, S> HopscotchHash<K, V, S>
136	where
137	    K: Hash + Eq,
138	    S: BuildHasher,
139	{
140	    /// An empty table using `hash_builder`.
141	    pub fn with_hasher(hash_builder: S) -> HopscotchHash<K, V, S> {
142	        HopscotchHash {
143	            buckets: Vec::new(),
144	            overflow: Vec::new(),
145	            bucket_count: 0,
146	            len: 0,
147	            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
148	            grow_at: 0,
149	            hash_builder,
150	        }
151	    }
152	
153	    /// An empty table using `hash_builder`, sized for `capacity` entries.
154	    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> HopscotchHash<K, V, S> {
155	        let mut table = HopscotchHash::with_hasher(hash_builder);
156	        table.reserve(capacity);
157	        table
158	    }
159	
160	    /// Number of entries stored.
161	    pub fn len(&self) -> usize {
162	        self.len
163	    }
164	
165	    /// True when no entry is stored.
166	    pub fn is_empty(&self) -> bool {
167	        self.len == 0
168	    }
169	
170	    /// Number of home buckets (a power of two, or zero when unallocated).
171	    pub fn bucket_count(&self) -> usize {
172	        self.bucket_count
173	    }
174	
175	    /// Number of slots in the bucket array, including the trailing overflow
176	    /// slack that keeps neighbourhoods from wrapping.
177	    pub fn slots(&self) -> usize {
178	        self.buckets.len()
179	    }
180	
181	    /// Number of entries that did not fit into any neighbourhood.
182	    pub fn overflow_len(&self) -> usize {
183	        self.overflow.len()
184	    }
185	
186	    /// Number of entries the table can hold before it grows.
187	    pub fn capacity(&self) -> usize {
188	        self.grow_at
189	    }
190	
191	    /// `len / bucket_count`, or `0.0` while unallocated.
192	    pub fn load_factor(&self) -> f32 {
193	        if self.bucket_count == 0 {
194	            0.0
195	        } else {
196	            self.len as f32 / self.bucket_count as f32
197	        }
198	    }
199	
200	    /// The load factor above which the table doubles.
201	    pub fn max_load_factor(&self) -> f32 {
202	        self.max_load_factor
203	    }
204	
205	    /// Sets the growth threshold, rehashing immediately if already exceeded.
206	    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
207	        assert!(
208	            max_load_factor > 0.0 && max_load_factor <= 1.0,
209	            "max_load_factor must be in (0.0, 1.0]"
210	        );
211	        self.max_load_factor = max_load_factor;
212	        self.grow_at = grow_threshold(self.bucket_count, max_load_factor);
213	        if self.bucket_count != 0 && self.len > self.grow_at {
214	            self.reserve(self.len);
215	        }
216	    }
217	
218	    /// A reference to the table's hash builder.
219	    pub fn hasher(&self) -> &S {
220	        &self.hash_builder
221	    }
222	
223	    /// Grows the table so `additional` more entries fit without a rehash.
224	    pub fn reserve(&mut self, additional: usize) {
225	        let wanted = self.len.saturating_add(additional);
226	        if wanted <= self.grow_at {
227	            return;
228	        }
229	        self.rehash(wanted);
230	    }
231	
232	    /// Rehashes into the smallest power-of-two bucket count that can hold
233	    /// `min_entries` entries within the maximum load factor.
234	    pub fn rehash(&mut self, min_entries: usize) {
235	        let needed = min_entries.max(self.len);
236	        let mut bucket_count = INITIAL_BUCKET_COUNT;
237	        while grow_threshold(bucket_count, self.max_load_factor) < needed {
238	            bucket_count = bucket_count
239	                .checked_mul(2)
240	                .expect("hopscotch table bucket count overflowed usize");
241	        }
242	        if bucket_count != self.bucket_count {
243	            self.rehash_to(bucket_count);
244	        }
245	    }
246	
247	    /// Removes every entry, keeping the allocated buckets.
248	    pub fn clear(&mut self) {
249	        for bucket in &mut self.buckets {
250	            bucket.neighbourhood = 0;
251	            bucket.entry = None;
252	        }
253	        self.overflow.clear();
254	        self.len = 0;
255	    }
256	
257	    fn hash_of(&self, key: &K) -> u64 {
258	        let mut hasher = self.hash_builder.build_hasher();
259	        key.hash(&mut hasher);
260	        hasher.finish()
261	    }
262	
263	    /// The home bucket of `key`; only valid once buckets are allocated.
264	    fn home_of(&self, key: &K) -> usize {
265	        debug_assert!(self.bucket_count.is_power_of_two());
266	        (self.hash_of(key) & (self.bucket_count as u64 - 1)) as usize
267	    }
268	
269	    /// Position of `key`, or `None` when absent.
270	    pub fn find(&self, key: &K) -> Option<Pos> {
271	        if self.bucket_count != 0 {
272	            let home = self.home_of(key);
273	            let mut bits = self.buckets[home].neighbourhood;
274	            while bits != 0 {
275	                let offset = bits.trailing_zeros() as usize;
276	                if let Some((stored, _)) = self.buckets[home + offset].entry.as_ref() {
277	                    if stored == key {
278	                        return Some(home + offset);
279	                    }
280	                }
281	                bits &= bits - 1;
282	            }
283	        }
284	        // Only pathological hashers ever populate the overflow list, so this
285	        // scan is skipped entirely in the common case.
286	        for (index, (stored, _)) in self.overflow.iter().enumerate() {
287	            if stored == key {
288	                return Some(self.buckets.len() + index);
289	            }
290	        }
291	        None
292	    }
293	
294	    /// True when `key` is present.
295	    pub fn contains_key(&self, key: &K) -> bool {
296	        self.find(key).is_some()
297	    }
298	
299	    /// The value stored for `key`.
300	    pub fn get(&self, key: &K) -> Option<&V> {
301	        let pos = self.find(key)?;
302	        self.entry_at(pos).map(|entry| &entry.1)
303	    }
304	
305	    /// A mutable reference to the value stored for `key`.
306	    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
307	        let pos = self.find(key)?;
308	        self.entry_at_mut(pos).map(|entry| &mut entry.1)
309	    }
310	
311	    /// The key/value pair stored for `key`.
312	    pub fn get_key_value(&self, key: &K) -> Option<(&K, &V)> {
313	        let pos = self.find(key)?;
314	        self.entry_at(pos).map(|entry| (&entry.0, &entry.1))
315	    }
316	
317	    /// Inserts `key`/`value` unless `key` is already present.
318	    ///
319	    /// Mirrors `std::unordered_map::insert`: the returned flag is `true` when
320	    /// the entry was inserted and `false` when an equivalent key already
321	    /// existed, in which case the stored value is left untouched.  The returned
322	    /// [`Pos`] designates the entry for `key` either way.
323	    pub fn insert(&mut self, key: K, value: V) -> (Pos, bool) {
324	        if let Some(pos) = self.find(&key) {
325	            return (pos, false);
326	        }
327	        if self.bucket_count == 0 || self.len + 1 > self.grow_at {
328	            self.grow();
329	        }
330	
331	        let entry = (key, value);
332	        for _ in 0..MAX_GROW_ATTEMPTS {
333	            let home = self.home_of(&entry.0);
334	            if let Some(slot) = self.free_slot_for(home) {
335	                self.buckets[home].neighbourhood |= 1u32 << (slot - home);
336	                self.buckets[slot].entry = Some(entry);
337	                self.len += 1;
338	                return (slot, true);
339	            }
340	            // The neighbourhood is saturated: a bigger table spreads it out.
341	            self.grow();
342	        }
343	
344	        self.overflow.push(entry);
345	        self.len += 1;
346	        (self.buckets.len() + self.overflow.len() - 1, true)
347	    }
348	
349	    /// Inserts `key`/`value`, overwriting any previous value.
350	    ///
351	    /// Mirrors `std::unordered_map::insert_or_assign`; the flag reports whether
352	    /// a new entry was created.
353	    pub fn insert_or_assign(&mut self, key: K, value: V) -> (Pos, bool) {
354	        if let Some(pos) = self.find(&key) {
355	            if let Some(entry) = self.entry_at_mut(pos) {
356	                entry.1 = value;
357	            }
358	            return (pos, false);
359	        }
360	        self.insert(key, value)
361	    }
362	
363	    /// Removes `key`, returning its value.
364	    pub fn remove(&mut self, key: &K) -> Option<V> {
365	        self.remove_entry(key).map(|(_, value)| value)
366	    }
367	
368	    /// Removes `key`, returning the whole pair.
369	    pub fn remove_entry(&mut self, key: &K) -> Option<(K, V)> {
370	        let pos = self.find(key)?;
371	        self.len -= 1;
372	        if pos < self.buckets.len() {
373	            let home = self.home_of(key);
374	            debug_assert!(pos >= home && pos - home < NEIGHBOURHOOD_SIZE);
375	            self.buckets[home].neighbourhood &= !(1u32 << (pos - home));
376	            self.buckets[pos].entry.take()
377	        } else {
378	            // `swap_remove` keeps the overflow list compact; overflow order is
379	            // unspecified anyway, exactly as in an unordered container.
380	            Some(self.overflow.swap_remove(pos - self.buckets.len()))
381	        }
382	    }
383	
384	    /// Doubles the bucket count (or performs the first allocation).
385	    fn grow(&mut self) {
386	        let bucket_count = if self.bucket_count == 0 {
387	            INITIAL_BUCKET_COUNT
388	        } else {
389	            self.bucket_count
390	                .checked_mul(2)
391	                .expect("hopscotch table bucket count overflowed usize")
392	        };
393	        self.rehash_to(bucket_count);
394	    }
395	
396	    /// Reallocates to exactly `bucket_count` home buckets and reinserts.
397	    fn rehash_to(&mut self, bucket_count: usize) {
398	        debug_assert!(bucket_count.is_power_of_two());
399	
400	        let old_buckets = std::mem::replace(&mut self.buckets, new_buckets(bucket_count));
401	        let old_overflow = std::mem::take(&mut self.overflow);
402	        self.bucket_count = bucket_count;
403	        self.grow_at = grow_threshold(bucket_count, self.max_load_factor);
404	        self.len = 0;
405	
406	        for bucket in old_buckets {
407	            if let Some(entry) = bucket.entry {
408	                self.place(entry);
409	            }
410	        }
411	        for entry in old_overflow {
412	            self.place(entry);
413	        }
414	    }
415	
416	    /// Stores an entry known to be absent, without growing the table.
417	    ///
418	    /// Used while rehashing, where growing would recurse; entries that cannot
419	    /// reach their neighbourhood land in the overflow list instead.
420	    fn place(&mut self, entry: (K, V)) {
421	        let home = self.home_of(&entry.0);
422	        match self.free_slot_for(home) {
423	            Some(slot) => {
424	                self.buckets[home].neighbourhood |= 1u32 << (slot - home);
425	                self.buckets[slot].entry = Some(entry);
426	            }
427	            None => self.overflow.push(entry),
428	        }
429	        self.len += 1;
430	    }
431	
432	    /// Finds a vacant slot inside `home`'s neighbourhood, hopping entries
433	    /// backwards as needed.  `None` when the neighbourhood cannot be freed.
434	    fn free_slot_for(&mut self, home: usize) -> Option<usize> {
435	        let mut slot = self.probe_for_vacant(home)?;
436	        while slot - home >= NEIGHBOURHOOD_SIZE {
437	            slot = self.hop_closer(slot)?;
438	        }
439	        Some(slot)
440	    }
441	
442	    /// First vacant slot at or after `home`, within the probe limit.
443	    fn probe_for_vacant(&self, home: usize) -> Option<usize> {
444	        let end = self.buckets.len().min(home + MAX_PROBE_LENGTH);
445	        (home..end).find(|&slot| self.buckets[slot].is_vacant())
446	    }
447	
448	    /// Moves some entry into the vacant `slot`, returning the slot it freed —
449	    /// always closer to the start of the array.  `None` when no entry within
450	    /// reach of `slot` can legally move into it.
451	    fn hop_closer(&mut self, slot: usize) -> Option<usize> {
452	        debug_assert!(self.buckets[slot].is_vacant());
453	        debug_assert!(slot >= NEIGHBOURHOOD_SIZE);
454	
455	        // Candidate home buckets whose neighbourhood still reaches `slot`.
456	        let first_home = slot + 1 - NEIGHBOURHOOD_SIZE;
457	        for home in first_home..slot {
458	            if home >= self.bucket_count {
459	                break; // Trailing slack slots are never home buckets.
460	            }
461	            let distance = (slot - home) as u32;
462	            // Entries closer to `home` than `slot` is: those can move up.
463	            let reachable = self.buckets[home].neighbourhood & ((1u32 << distance) - 1);
464	            if reachable == 0 {
465	                continue;
466	            }
467	            let offset = reachable.trailing_zeros();
468	            let source = home + offset as usize;
469	            let entry = self.buckets[source]
470	                .entry
471	                .take()
472	                .expect("neighbourhood bitmap pointed at a vacant slot");
473	            self.buckets[slot].entry = Some(entry);
474	            self.buckets[home].neighbourhood &= !(1u32 << offset);
475	            self.buckets[home].neighbourhood |= 1u32 << distance;
476	            return Some(source);
477	        }
478	        None
479	    }
