486	    /// Position of the first entry, or [`end_pos`](Self::end_pos) when empty.
487	    pub fn first_pos(&self) -> Pos {
488	        let mut pos = 0;
489	        while pos < self.buckets.len() && self.buckets[pos].is_vacant() {
490	            pos += 1;
491	        }
492	        pos
493	    }
494	
495	    /// Position following `pos` in iteration order, clamped to `end_pos()`.
496	    pub fn pos_after(&self, pos: Pos) -> Pos {
497	        let end = self.end_pos();
498	        if pos >= end {
499	            return end;
500	        }
501	        let mut next = pos + 1;
502	        while next < self.buckets.len() && self.buckets[next].is_vacant() {
503	            next += 1;
504	        }
505	        next
506	    }
