508	    /// The entry at `pos`, or `None` when `pos` is not a live position.
509	    pub fn entry_at(&self, pos: Pos) -> Option<&(K, V)> {
510	        if pos < self.buckets.len() {
511	            self.buckets[pos].entry.as_ref()
512	        } else {
513	            self.overflow.get(pos - self.buckets.len())
514	        }
515	    }
516	
517	    /// The entry at `pos`, mutably.
518	    pub fn entry_at_mut(&mut self, pos: Pos) -> Option<&mut (K, V)> {
519	        if pos < self.buckets.len() {
520	            self.buckets[pos].entry.as_mut()
521	        } else {
522	            let index = pos - self.buckets.len();
523	            self.overflow.get_mut(index)
524	        }
525	    }
