533	/// Allocates a vacant bucket array with the trailing anti-wrap slack.
534	fn new_buckets<K, V>(bucket_count: usize) -> Vec<Bucket<K, V>> {
535	    let slots = bucket_count
536	        .checked_add(NEIGHBOURHOOD_SIZE - 1)
537	        .expect("hopscotch table slot count overflowed usize");
538	    let mut buckets = Vec::with_capacity(slots);
539	    for _ in 0..slots {
540	        buckets.push(Bucket::vacant());
541	    }
542	    buckets
543	}
