546	fn grow_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
547	    if bucket_count == 0 {
548	        return 0;
549	    }
550	    let threshold = (bucket_count as f64 * max_load_factor as f64) as usize;
551	    threshold.max(1)
