use std::os::unix::ffi::OsStrExt;
#[derive(Debug,PartialEq)] enum E { Invalid, Range }
fn is_sp(b:u8)->bool{ matches!(b, 0x20|0x09|0x0A|0x0B|0x0C|0x0D) }
fn stoi(s:&[u8])->Result<i32,E>{
    let mut i=0; while i<s.len() && is_sp(s[i]) { i+=1; }
    let mut neg=false;
    if i<s.len() && (s[i]==b'+'||s[i]==b'-') { neg = s[i]==b'-'; i+=1; }
    if i>=s.len() || !s[i].is_ascii_digit() { return Err(E::Invalid); }
    let mut acc: i64 = 0;
    while i<s.len() && s[i].is_ascii_digit() {
        acc = acc.saturating_mul(10).saturating_add((s[i]-b'0') as i64);
        if acc > (u32::MAX as i64) { acc = u32::MAX as i64 + 1; } // clamp, keeps out-of-range
        i+=1;
    }
    let v = if neg { -acc } else { acc };
    if v < i32::MIN as i64 || v > i32::MAX as i64 { return Err(E::Range); }
    Ok(v as i32)
}
